<?php
require_once __DIR__.'/includes/bootstrap.php'; require_login(); $u=current_user(); $rows=[];
if($db){$st=$db->prepare('SELECT i.*,o.order_number FROM invoices i LEFT JOIN orders o ON o.id=i.order_id WHERE i.user_id=? ORDER BY i.id DESC');$st->execute([$u['id']]);$rows=$st->fetchAll();}
?><!doctype html><html lang="<?=e($LANG)?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Invoices — WDH</title><link rel="stylesheet" href="assets/css/style.css?v=wdh-ui-v8"><link rel="stylesheet" href="assets/css/catalog.css?v=wdh-ui-v8"></head><body><?php require __DIR__.'/includes/header.php';?><main class="simple-page"><div class="breadcrumbs">Home › Client Portal › Invoices</div><div class="portal-welcome"><div><span class="eyebrow mint">BILLING</span><h1>Invoices</h1><p>Your WDH billing history.</p></div></div><div class="admin-table"><?php if(!$rows):?><div class="empty">No invoices yet. New invoices will appear here after an order is created.</div><?php else:foreach($rows as $r):?><div class="admin-row"><div><strong><?=e($r['invoice_number'])?></strong><small>Order <?=e($r['order_number']??'')?> · <?=e($r['created_at'])?></small></div><span><?=money($r['total'],$r['currency'])?></span><strong><?=e(ucfirst($r['status']))?></strong><a class="btn secondary small" href="order-details.php?order=<?=urlencode($r['order_number']??'')?>">View</a></div><?php endforeach;endif;?></div></main><?php require __DIR__.'/includes/footer.php';?></body></html>
